files.main.tf:
module "queue" {
  source = "./modules/queue"
  retention_seconds = var.retention_seconds
}
resource "terraform_data" "dispatch" {
  input = module.queue.limit
}
output "dispatch_limit" {
  value = terraform_data.dispatch.output
}

files.variables.tf:
variable "retention_seconds" {
  type = number
  default = 60
  validation {
    condition = var.retention_seconds >= 60 && var.retention_seconds <= 900
    error_message = "Retention must be between 60 and 900 seconds."
  }
}

files.modules/queue/main.tf:
variable "retention_seconds" { type = number }
locals {
  bounded_retention = min(var.retention_seconds, 300)
}
output "limit" {
  value = local.bounded_retention
}

files.worker.nomad.hcl:
job "worker" {
  datacenters = ["dc1"]
  type = "service"
  group "processors" {
    count = 2
    shutdown_delay = "${var.drain_seconds}s"
    task "consumer" {
      driver = "docker"
      config { image = "example.invalid/worker:1.2" }
      resources { cpu = 200 }
    }
  }
}

files.metrics.nomad.hcl:
job "metrics" {
  datacenters = ["dc1"]
  type = "batch"
  group "reporters" {
    task "report" {
      driver = "raw_exec"
      config { command = "/bin/true" }
    }
  }
}

files.templates/_helpers.tpl:
{{- define "parcel.labels" -}}
app.kubernetes.io/name: {{ .Chart.Name | quote }}
app.kubernetes.io/instance: {{ .Release.Name | quote }}
{{- end -}}

files.templates/service.yaml:
apiVersion: v1
kind: Service
metadata:
  name: {{ .Release.Name }}
spec:
  selector:
    {{- include "parcel.labels" . | nindent 4 }}
  ports:
    - port: {{ .Values.service.port }}
      targetPort: {{ .Values.service.port }}

files.deliver.sh:
#!/usr/bin/env bash
set -euo pipefail
source "./lib/policy.sh"
deliver_payload() {
  local payload="$1"
  local attempt="$2"
  local delay
  delay=$(retry_delay "$attempt")
  sleep "$delay"
  printf '%s\n' "$payload" | consume_payload
}
consume_payload() {
  cat
}
health_probe() {
  printf '%s\n' ok
}

files.lib/policy.sh:
#!/usr/bin/env bash
retry_delay() {
  local attempt="$1"
  local delay=$((1 << attempt))
  if (( delay > 45 )); then
    delay=45
  fi
  printf '%s\n' "$delay"
}
